mapper.update:
update pw_async_task
set status = 'PENDING',
    retry_count = retry_count + 1,
    next_retry_at = #{nextRetryAt},
    lease_until = null,
    last_error = #{lastError}
where id = #{id}
  and status = 'PROCESSING'
  and lease_until = #{leaseUntil}

update pw_async_task
set status = 'FAILED',
    retry_count = least(retry_count + 1, max_retry_count),
    next_retry_at = null,
    lease_until = null,
    last_error = #{lastError}
where id = #{id}
  and status = 'PROCESSING'
  and lease_until = #{leaseUntil}
